"""The player cadence evolves. Each round it starts from the current champion.

It runs in its own process and is sent plain JSON each turn, so it sees only
what a player may see. Everything outside the markers stays put.
"""


# CADENCE:BEGIN
def choose(view: dict, moves: list[dict]) -> int:
    """Return one of `moves`. `view` is everything this player may see."""
    if not moves:
        return 0

    import random
    from scrabble import tools

    # Seed any randomness from the view's current position
    rng = random.Random(view.get("cgp", ""))

    # Standard heuristic values for keeping tiles on the rack
    VAL = {
        "A": 1.0,
        "B": -2.0,
        "C": -0.5,
        "D": 0.5,
        "E": 2.5,
        "F": -1.5,
        "G": -0.5,
        "H": 1.0,
        "I": 0.5,
        "J": -2.5,
        "K": -1.5,
        "L": 1.0,
        "M": 1.0,
        "N": 1.5,
        "O": -0.5,
        "P": 0.5,
        "Q": -6.0,
        "R": 2.0,
        "S": 8.0,
        "T": 1.5,
        "U": -1.5,
        "V": -3.5,
        "W": -2.0,
        "X": 1.5,
        "Y": -0.5,
        "Z": -2.0,
        "?": 25.0,
    }

    # Standard Scrabble letter values for endgame penalty/bonus calculations
    TILE_VALUES = {
        "A": 1,
        "B": 3,
        "C": 3,
        "D": 2,
        "E": 1,
        "F": 4,
        "G": 2,
        "H": 4,
        "I": 1,
        "J": 8,
        "K": 5,
        "L": 1,
        "M": 3,
        "N": 1,
        "O": 1,
        "P": 3,
        "Q": 10,
        "R": 1,
        "S": 1,
        "T": 1,
        "U": 1,
        "V": 4,
        "W": 4,
        "X": 8,
        "Y": 4,
        "Z": 10,
        "?": 0,
    }

    VOWELS = {"A", "E", "I", "O", "U"}

    bag_size = view.get("bag", 100)
    if hasattr(bag_size, "__len__"):
        bag_size = len(bag_size)

    grid = view.get("grid")
    TWS = {(0, 0), (0, 7), (0, 14), (7, 0), (7, 14), (14, 0), (14, 7), (14, 14)}

    if grid:
        open_tws_board = {pos for pos in TWS if grid[pos[0]][pos[1]] is None}
    else:
        open_tws_board = TWS.copy()

    def get_leave_val(leave, b_size):
        if not leave:
            return 0.0
        leave_weight = max(0.0, min(1.0, b_size / 7.0))
        leave_val = 0.0
        has_q = "Q" in leave
        has_u = "U" in leave
        for char in leave:
            val = VAL.get(char, 0.0)
            if char == "Q" and has_u:
                val = 2.0
            elif char == "U" and has_q:
                val = 1.0
            leave_val += val

        if has_q and not has_u:
            leave_val -= 8.0

        # Penalize duplicate letters
        counts = {}
        for char in leave:
            if char != "?":
                counts[char] = counts.get(char, 0) + 1
        for char, count in counts.items():
            if count > 1:
                leave_val -= (count - 1) * (1.0 if char == "S" else 2.5)

        # Maintain a healthy vowel/consonant balance (target ~43% vowels)
        vowels = 0
        consonants = 0
        for c in leave:
            if c in VOWELS:
                vowels += 1
            elif c != "?":
                consonants += 1

        total = vowels + consonants
        if total > 1:
            ideal_v = round(total * 0.43)
            leave_val -= abs(vowels - ideal_v) * 2.0

        return leave_val * leave_weight

    def get_tws_penalty(move, grid, open_tws_board):
        tws_penalty = 0.0
        if move["kind"] == "play" and move["tiles"] and grid:
            move_coords = {(t[0], t[1]) for t in move["tiles"]}
            tws_dists = {}
            for r, col, _, _ in move["tiles"]:
                if r in (0, 7, 14):
                    for tc in (0, 7, 14):
                        if (r, tc) in open_tws_board and (r, tc) not in move_coords:
                            dist = abs(col - tc)
                            if 1 <= dist <= 3:
                                step = 1 if tc > col else -1
                                blocked = False
                                for c_mid in range(col + step, tc, step):
                                    if grid[r][c_mid] is not None:
                                        blocked = True
                                        break
                                if not blocked:
                                    tws_dists[(r, tc)] = min(
                                        tws_dists.get((r, tc), 99), dist
                                    )
                if col in (0, 7, 14):
                    for tr in (0, 7, 14):
                        if (tr, col) in open_tws_board and (tr, col) not in move_coords:
                            dist = abs(r - tr)
                            if 1 <= dist <= 3:
                                step = 1 if tr > r else -1
                                blocked = False
                                for r_mid in range(r + step, tr, step):
                                    if grid[r_mid][col] is not None:
                                        blocked = True
                                        break
                                if not blocked:
                                    tws_dists[(tr, col)] = min(
                                        tws_dists.get((tr, col), 99), dist
                                    )

            for (tr, tc), dist in tws_dists.items():
                tws_penalty += 10.0 if dist == 1 else (5.0 if dist == 2 else 3.0)
        return tws_penalty

    # Pre-score all moves using the champion's fast heuristic
    scored_moves = []
    for idx, move in enumerate(moves):
        score = move["score"]
        leave = [c.upper() for c in move["leave"]] if move["leave"] is not None else []
        leave_val = get_leave_val(leave, bag_size)
        tws_penalty = get_tws_penalty(move, grid, open_tws_board)
        heuristic_score = score + leave_val - tws_penalty
        scored_moves.append((heuristic_score, idx, move))

    # Sort moves descending by heuristic score
    scored_moves.sort(key=lambda x: x[0], reverse=True)

    if bag_size == 0:
        # Endgame: exact opponent rack is fully known. Run 2-ply minimax.
        world = tools.sample_world(view["cgp"], rng)

        unseen_tiles = []
        unseen = view.get("unseen", {})
        if hasattr(unseen, "items"):
            for char, count in unseen.items():
                unseen_tiles.extend([char.upper()] * count)
        elif hasattr(unseen, "__iter__"):
            for char in unseen:
                unseen_tiles.append(char.upper())

        best_idx = scored_moves[0][1]
        best_tie_breaker = (-float('inf'), -float('inf'), False)

        K = min(30, len(moves))
        for h_score, idx, move in scored_moves[:K]:
            after = tools.play(world, idx)
            our_leave = [c.upper() for c in move["leave"]] if move["leave"] is not None else []

            if tools.over(after):
                val = tools.spread(after, view["me"])
            else:
                opp_moves = tools.legal(after)
                if not opp_moves:
                    # Opponent has no moves and must pass
                    val = tools.spread(after, view["me"]) - sum(TILE_VALUES.get(c, 0) for c in our_leave) + sum(TILE_VALUES.get(c, 0) for c in unseen_tiles)
                else:
                    best_opp_val = float('inf')
                    for om in opp_moves:
                        after2 = tools.play(after, om)
                        om_leave = [c.upper() for c in om["leave"]] if om["leave"] is not None else []
                        if tools.over(after2):
                            opp_val = tools.spread(after2, view["me"])
                        else:
                            opp_val = tools.spread(after2, view["me"]) - sum(TILE_VALUES.get(c, 0) for c in our_leave) + sum(TILE_VALUES.get(c, 0) for c in om_leave)
                        if opp_val < best_opp_val:
                            best_opp_val = opp_val
                    val = best_opp_val

            tie_breaker = (val, move["score"], move["kind"] == "play")
            if tie_breaker > best_tie_breaker:
                best_tie_breaker = tie_breaker
                best_idx = idx

        return best_idx

    else:
        # Midgame/Pre-endgame: Sample S worlds to find the robust best move
        S = 4
        C = min(8, len(moves))
        worlds = [tools.sample_world(view["cgp"], rng) for _ in range(S)]

        candidate_scores = {idx: 0.0 for _, idx, _ in scored_moves[:C]}

        for world in worlds:
            for _, idx, move in scored_moves[:C]:
                after = tools.play(world, idx)
                our_leave = [c.upper() for c in move["leave"]] if move["leave"] is not None else []

                if tools.over(after):
                    val = tools.spread(after, view["me"])
                else:
                    opp_moves = tools.legal(after)
                    bag_size_after = max(0, bag_size - len(move.get("tiles", []))) if move["kind"] == "play" else bag_size

                    if not opp_moves:
                        val = tools.spread(after, view["me"]) + get_leave_val(our_leave, bag_size_after) - get_tws_penalty(move, grid, open_tws_board)
                    else:
                        best_opp_util = -float('inf')
                        best_om = None
                        for om in opp_moves:
                            opp_leave = [c.upper() for c in om["leave"]] if om["leave"] is not None else []
                            opp_util = om["score"] + get_leave_val(opp_leave, bag_size_after)
                            if opp_util > best_opp_util:
                                best_opp_util = opp_util
                                best_om = om

                        best_opp_leave = [c.upper() for c in best_om["leave"]] if best_om["leave"] is not None else []
                        val = (tools.spread(after, view["me"]) - best_om["score"] 
                               + get_leave_val(our_leave, bag_size_after) 
                               - get_leave_val(best_opp_leave, bag_size_after)
                               - get_tws_penalty(move, grid, open_tws_board))

                candidate_scores[idx] += val

        # Find the best candidate using the tie-breaker
        best_idx = scored_moves[0][1]
        best_tie_breaker = (-float('inf'), -float('inf'), False)
        for _, idx, move in scored_moves[:C]:
            avg_val = candidate_scores[idx] / S
            tie_breaker = (avg_val, move["score"], move["kind"] == "play")
            if tie_breaker > best_tie_breaker:
                best_tie_breaker = tie_breaker
                best_idx = idx

        return best_idx
# CADENCE:END
